/* Facility Compliance Interface — prototype rules engine + wizard UI.
 * All reference data lives in data/*.json (generated by scripts/build_data.py
 * from Facility_Compliance_Parameter_Schema.xlsx). This file never edits
 * that data — it only renders it and evaluates entered values against it.
 */

// ---------------------------------------------------------------------
// Constants not carried in the data files (UI-only groupings)
// ---------------------------------------------------------------------

// Category and dosage-form lists are shared with saved-project validation.
const { CATEGORY_DEFS, SPECIFIC_FORMS, resolveInputKind } = ProjectState;

const OPTION_OVERRIDES = {
  "UTIL-001": ["Class 1", "Class 1.2.1", "Class 2"],
  "SHE-004": ["OEB 1", "OEB 2", "OEB 3", "OEB 4", "OEB 5"],
  "HVAC-001": ["Unclassified/CNC", "Grade D (ISO 8)", "Grade C (ISO 7)", "Grade B", "Grade A (ISO 5)"],
};

const {
  GRADE_HIERARCHY, GRADE_TAG_TO_LABEL, SEVERITY_RANK, NON_SCORED_CATEGORY_EXCLUDE, PARAM_ROOM_FILTERS,
} = FacilityEngine;

const SEVERITY_ORDER = ["Critical", "Significant", "Partial", "Aligned"];

// ---------------------------------------------------------------------
// State
// ---------------------------------------------------------------------

const state = {
  step: 1,
  category: null,
  devStage: null,
  specificForms: [],
  targetMarkets: ["schedule_m"],
  scaleSize: "Medium",
  batchSize: "",
  selectedRooms: [],
  facilityValues: {}, // paramId -> value
  roomValues: {}, // roomId -> { paramId -> value }
};

let DATA = null; // populated by loadData()

// ---------------------------------------------------------------------
// DOM helper
// ---------------------------------------------------------------------

function h(tag, attrs = {}, children = []) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === null || v === undefined) continue;
    // No "html" option on purpose: every string reaches the page as text (R7/R8).
    if (k === "html") throw new Error('h(): "html" is not supported; pass text or elements as children');
    if (k === "class") el.className = v;
    else if (k.startsWith("on")) {
      if (typeof v !== "function") throw new Error(`h(): ${k} must be a function, not a string`);
      el.addEventListener(k.slice(2), v);
    } else el.setAttribute(k, v);
  }
  (Array.isArray(children) ? children : [children]).forEach((c) => {
    if (c === null || c === undefined || c === false) return;
    el.appendChild(typeof c === "string" || typeof c === "number" ? document.createTextNode(c) : c);
  });
  return el;
}

// SVG counterpart of h() for the results charts. Same rules: no "html", no
// string event handlers, and no inline "style" (blocked by the CSP — colour
// comes from CSS classes; geometry from SVG attributes).
const SVG_NS = "http://www.w3.org/2000/svg";
function s(tag, attrs = {}, children = []) {
  const el = document.createElementNS(SVG_NS, tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === null || v === undefined) continue;
    if (k === "html") throw new Error('s(): "html" is not supported; pass text or elements as children');
    if (k === "style") throw new Error('s(): inline "style" is blocked by the CSP; use a class');
    if (k.startsWith("on")) {
      if (typeof v !== "function") throw new Error(`s(): ${k} must be a function, not a string`);
      el.addEventListener(k.slice(2), v);
    } else el.setAttribute(k, v);
  }
  (Array.isArray(children) ? children : [children]).forEach((c) => {
    if (c === null || c === undefined || c === false) return;
    el.appendChild(typeof c === "string" || typeof c === "number" ? document.createTextNode(c) : c);
  });
  return el;
}

function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
}

// ---------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------

async function loadData() {
  const files = ["parameters", "rooms", "thresholds", "boolean_thresholds", "authorities", "structural_flags"];
  const results = await Promise.all(files.map((f) => fetch(`data/${f}.json`).then((r) => r.json())));
  const data = {};
  files.forEach((f, i) => (data[f] = results[i]));
  // Optional: without provenance every result shows "Citation pending" / "Unclassified".
  data.provenance = await fetch("data/provenance.json").then((r) => (r.ok ? r.json() : null)).catch(() => null);
  return FacilityEngine.indexData(data);
}

// ---------------------------------------------------------------------
// Step 1 — Classification
// ---------------------------------------------------------------------

function renderStep1() {
  const root = document.getElementById("step-1");
  clear(root);

  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 1 — Classification"));

  panel.appendChild(h("h3", {}, "Dosage Form Category"));
  const grid = h("div", { class: "choice-grid" });
  CATEGORY_DEFS.forEach((c) => {
    const card = h(
      "button",
      {
        type: "button",
        class: "choice-card" + (state.category === c.key ? " selected" : ""),
        onclick: () => {
          state.category = c.key;
          state.specificForms = [];
          state.devStage = null;
          state.selectedRooms = [];
          renderStep1();
        },
      },
      [h("strong", {}, c.label), h("span", {}, c.desc)]
    );
    grid.appendChild(card);
  });
  panel.appendChild(grid);

  if (state.category === "osd_rnd_pilot") {
    panel.appendChild(h("h3", {}, "Facility Development Stage"));
    panel.appendChild(h("p", { class: "field-hint" }, "Schedule M has no dedicated chapter for either — this only affects the wording of the structural-gap notice in your results."));
    const devGrid = h("div", { class: "choice-grid" });
    ["R&D Lab", "Pilot Plant"].forEach((stg) => {
      devGrid.appendChild(
        h(
          "button",
          {
            type: "button",
            class: "choice-card" + (state.devStage === stg ? " selected" : ""),
            onclick: () => {
              state.devStage = stg;
              renderStep1();
            },
          },
          h("strong", {}, stg)
        )
      );
    });
    panel.appendChild(devGrid);
  }

  if (state.category) {
    panel.appendChild(h("h3", {}, "Specific Dosage Form(s)"));
    panel.appendChild(h("p", { class: "field-hint" }, "Selecting MDF, Buccal Film, or Implant will flag a Schedule M regulatory vacuum in your results."));
    const formGrid = h("div", { class: "checkbox-list" });
    SPECIFIC_FORMS[state.category].forEach((form) => {
      const id = "form-" + form.replace(/[^a-z0-9]/gi, "");
      const row = h("label", { class: "check-row", for: id }, [
        h("input", {
          type: "checkbox",
          id,
          checked: state.specificForms.includes(form) ? "checked" : null,
          onchange: (e) => {
            if (e.target.checked) state.specificForms.push(form);
            else state.specificForms = state.specificForms.filter((f) => f !== form);
          },
        }),
        h("span", { class: "row-label" }, form),
      ]);
      formGrid.appendChild(row);
    });
    panel.appendChild(formGrid);
  }

  panel.appendChild(h("h3", {}, "Target Regulatory Market(s)"));
  panel.appendChild(h("p", { class: "field-hint" }, "Schedule M is pre-selected as the home authority. Markets marked “not covered” have no data in this dataset — they'll show as such rather than being silently guessed."));
  const marketGrid = h("div", { class: "market-grid" });
  DATA.authorities.forEach((a) => {
    const id = "mkt-" + a.key;
    const row = h("label", { class: "check-row" + (a.covered ? "" : " uncovered"), for: id }, [
      h("input", {
        type: "checkbox",
        id,
        checked: state.targetMarkets.includes(a.key) ? "checked" : null,
        onchange: (e) => {
          if (e.target.checked) state.targetMarkets.push(a.key);
          else state.targetMarkets = state.targetMarkets.filter((k) => k !== a.key);
        },
      }),
      h("span", {}, [
        h("span", { class: "row-label" }, a.label),
        !a.covered ? h("span", { class: "badge uncovered" }, "not covered") : null,
        a.shared_note ? h("span", { class: "row-meta" }, a.shared_note) : null,
      ]),
    ]);
    marketGrid.appendChild(row);
  });
  panel.appendChild(marketGrid);

  panel.appendChild(h("h3", {}, "Facility Scale"));
  const scaleRow = h("div", { class: "field-row" });
  scaleRow.appendChild(
    h("div", { class: "field-block narrow" }, [
      h("label", {}, "Scale"),
      h(
        "select",
        { onchange: (e) => (state.scaleSize = e.target.value) },
        ["Small", "Medium", "Large"].map((s) => h("option", { value: s, selected: state.scaleSize === s ? "selected" : null }, s))
      ),
    ])
  );
  scaleRow.appendChild(
    h("div", { class: "field-block narrow" }, [
      h("label", {}, "Batch size (kg or units)"),
      h("input", { type: "text", value: state.batchSize, oninput: (e) => (state.batchSize = e.target.value), placeholder: "e.g. 50,000 tablets" }),
    ])
  );
  panel.appendChild(scaleRow);
  panel.appendChild(h("p", { class: "field-hint" }, "No authority prescribes a room-area formula from batch size — this is captured for context only."));

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Step 2 — Room / Zone selection
// ---------------------------------------------------------------------

function applicableRooms() {
  if (!state.category) return [];
  return DATA.rooms.filter((r) => r.applies_to[state.category]);
}

function renderStep2() {
  const root = document.getElementById("step-2");
  clear(root);
  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 2 — Rooms & Zones"));
  panel.appendChild(h("p", { class: "field-hint" }, "Select every room/zone you want assessed. Grouped by process stage, filtered to what applies to " + (CATEGORY_DEFS.find((c) => c.key === state.category) || {}).label + "."));

  const rooms = applicableRooms();
  const byStage = {};
  rooms.forEach((r) => {
    byStage[r.process_stage] = byStage[r.process_stage] || [];
    byStage[r.process_stage].push(r);
  });

  Object.keys(byStage).forEach((stage) => {
    const group = h("div", { class: "room-group" });
    group.appendChild(h("h4", {}, stage));
    const list = h("div", { class: "checkbox-list" });
    byStage[stage].forEach((r) => {
      const id = "room-" + r.id;
      list.appendChild(
        h("label", { class: "check-row", for: id }, [
          h("input", {
            type: "checkbox",
            id,
            checked: state.selectedRooms.includes(r.id) ? "checked" : null,
            onchange: (e) => {
              if (e.target.checked) state.selectedRooms.push(r.id);
              else state.selectedRooms = state.selectedRooms.filter((x) => x !== r.id);
            },
          }),
          h("span", {}, [h("span", { class: "row-label" }, r.name), h("span", { class: "row-meta" }, r.typical_grade)]),
        ])
      );
    });
    group.appendChild(list);
    panel.appendChild(group);
  });

  if (!rooms.length) panel.appendChild(h("p", { class: "empty-hint" }, "No rooms found for this category — go back and pick a dosage form category first."));

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Step 3 — Parameter input
// ---------------------------------------------------------------------

function relevantParams() {
  return FacilityEngine.relevantParams(DATA, state);
}

const appliesAtNormalized = FacilityEngine.appliesAtNormalized;

function optionsFor(param) {
  if (OPTION_OVERRIDES[param.id]) return OPTION_OVERRIDES[param.id];
  const raw = param.unit_options || "";
  if (raw.includes(" / ")) return raw.split(" / ").map((s) => s.trim());
  return [raw];
}

function renderParamField(param, value, onChange) {
  const kind = resolveInputKind(param);
  const wrap = h("div", { class: "field-block" });
  wrap.appendChild(h("label", {}, param.name));

  if (kind === "number") {
    const unit = param.id === "DFS-003" ? "% RH" : param.unit_options;
    const input = h("input", {
      type: "number",
      step: "any",
      value: value === undefined || value === null ? "" : value,
      placeholder: unit || "",
      oninput: (e) => onChange(e.target.value === "" ? null : parseFloat(e.target.value)),
    });
    wrap.appendChild(input);
    if (unit) wrap.appendChild(h("span", { class: "field-note" }, unit));
  } else if (kind === "number-range") {
    const rowWrap = h("div", { class: "range-row" });
    const v = value || {};
    rowWrap.appendChild(
      h("input", {
        type: "number", step: "any", placeholder: "min", value: v.min ?? "",
        oninput: (e) => onChange({ ...v, min: e.target.value === "" ? null : parseFloat(e.target.value) }),
      })
    );
    rowWrap.appendChild(h("span", {}, "–"));
    rowWrap.appendChild(
      h("input", {
        type: "number", step: "any", placeholder: "max", value: v.max ?? "",
        oninput: (e) => onChange({ ...v, max: e.target.value === "" ? null : parseFloat(e.target.value) }),
      })
    );
    wrap.appendChild(rowWrap);
    if (param.unit_options) wrap.appendChild(h("span", { class: "field-note" }, param.unit_options));
  } else if (kind === "select") {
    const opts = optionsFor(param);
    const sel = h(
      "select",
      { onchange: (e) => onChange(e.target.value) },
      [h("option", { value: "" }, "— select —")].concat(opts.map((o) => h("option", { value: o, selected: value === o ? "selected" : null }, o)))
    );
    wrap.appendChild(sel);
  } else if (kind === "boolean") {
    const sel = h(
      "select",
      { onchange: (e) => onChange(e.target.value === "" ? null : e.target.value === "true") },
      [
        h("option", { value: "" }, "— select —"),
        h("option", { value: "true", selected: value === true ? "selected" : null }, "Yes"),
        h("option", { value: "false", selected: value === false ? "selected" : null }, "No"),
      ]
    );
    wrap.appendChild(sel);
  } else if (kind === "boolean-text") {
    const v = value || {};
    const sel = h(
      "select",
      { onchange: (e) => onChange({ ...v, value: e.target.value === "" ? null : e.target.value === "true" }) },
      [
        h("option", { value: "" }, "— select —"),
        h("option", { value: "true", selected: v.value === true ? "selected" : null }, "Yes"),
        h("option", { value: "false", selected: v.value === false ? "selected" : null }, "No"),
      ]
    );
    wrap.appendChild(sel);
    wrap.appendChild(
      h("input", { type: "text", placeholder: "Detail (method / zone rating / etc.)", value: v.text || "", oninput: (e) => onChange({ ...v, text: e.target.value }) })
    );
  } else {
    wrap.appendChild(h("textarea", { oninput: (e) => onChange(e.target.value) }, value || ""));
  }

  if (param.notes) wrap.appendChild(h("span", { class: "field-note" }, param.notes));
  return wrap;
}

function renderStep3() {
  const root = document.getElementById("step-3");
  clear(root);
  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 3 — Facility & Room Parameters"));

  const params = relevantParams();
  const facilityParams = params.filter((p) => appliesAtNormalized(p) === "facility");
  const roomParams = params.filter((p) => appliesAtNormalized(p) === "room");

  if (facilityParams.length) {
    panel.appendChild(h("h3", {}, "Facility-level parameters (entered once)"));
    const grouped = {};
    facilityParams.forEach((p) => {
      grouped[p.category] = grouped[p.category] || [];
      grouped[p.category].push(p);
    });
    Object.keys(grouped).forEach((cat) => {
      const row = h("div", { class: "field-row" });
      grouped[cat].forEach((p) => {
        row.appendChild(
          renderParamField(p, state.facilityValues[p.id], (val) => {
            state.facilityValues[p.id] = val;
          })
        );
      });
      panel.appendChild(row);
    });
  }

  const selectedRooms = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);
  if (!selectedRooms.length) {
    panel.appendChild(h("p", { class: "empty-hint" }, "No rooms selected — go back to Step 2."));
  }

  selectedRooms.forEach((room) => {
    state.roomValues[room.id] = state.roomValues[room.id] || {};
    const section = h("div", { class: "room-param-section" });
    section.appendChild(h("div", { class: "room-title" }, room.name));
    section.appendChild(h("div", { class: "room-sub" }, `${room.process_stage} · Typical grade: ${room.typical_grade}`));

    if (room.bundled_area_note) {
      section.appendChild(h("p", { class: "field-hint" }, "⚠ " + room.bundled_area_note));
    }

    // Room Net Area (special-cased: per-room Schedule M minimum lives on the room record)
    const areaWrap = h("div", { class: "field-row" });
    areaWrap.appendChild(
      h("div", { class: "field-block" }, [
        h("label", {}, "Room Net Area (m²)"),
        h("input", {
          type: "number", step: "any",
          value: state.roomValues[room.id]["DIM-001"] ?? "",
          oninput: (e) => (state.roomValues[room.id]["DIM-001"] = e.target.value === "" ? null : parseFloat(e.target.value)),
        }),
        h("span", { class: "field-note" }, room.min_area_sqm != null ? `Schedule M minimum: ${room.min_area_sqm} m²` : "Schedule M gives no numeric minimum for this room"),
      ])
    );
    section.appendChild(areaWrap);

    const applicableRoomParams = roomParams.filter((p) => {
      if (p.id === "DIM-001") return false; // rendered as a special-cased field above (tied to room.min_area_sqm)
      const filter = PARAM_ROOM_FILTERS[p.id];
      return filter ? filter(room) : true;
    });

    const grouped = {};
    applicableRoomParams.forEach((p) => {
      grouped[p.category] = grouped[p.category] || [];
      grouped[p.category].push(p);
    });
    Object.keys(grouped).forEach((cat) => {
      const row = h("div", { class: "field-row" });
      grouped[cat].forEach((p) => {
        row.appendChild(
          renderParamField(p, state.roomValues[room.id][p.id], (val) => {
            state.roomValues[room.id][p.id] = val;
          })
        );
      });
      section.appendChild(row);
    });

    panel.appendChild(section);
  });

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Rules engine
// ---------------------------------------------------------------------

// Evaluation logic lives in engine.js (pure, tested); renderStep4 calls
// FacilityEngine.evaluateAll(DATA, state).
const marketLabel = (mk) => FacilityEngine.marketLabel(DATA, mk);

function statusPillClass(status) {
  return {
    compliant: "status-compliant",
    non_compliant: "status-noncompliant",
    not_regulated: "status-notregulated",
    not_covered: "status-notcovered",
    no_value: "status-na",
  }[status] || "status-na";
}

function statusLabel(status) {
  return {
    compliant: "Compliant",
    non_compliant: "Non-Compliant",
    not_regulated: "Not regulated here",
    not_covered: "Not covered",
    no_value: "No value entered",
  }[status] || status;
}

function severityTagClass(sev) {
  return { Critical: "sev-critical", Significant: "sev-significant", Partial: "sev-partial", Aligned: "sev-aligned" }[sev] || "sev-partial";
}

// Mandatory / Recommended / Unclassified badge. Draft labels (inferred from note
// wording, not yet confirmed by the domain expert) say so.
function obligationBadge(obligation, status) {
  const text = { mandatory: "Mandatory", recommended: "Recommended", unclassified: "Unclassified" }[obligation] || "Unclassified";
  const suffix = status === "draft" ? " (draft)" : status === "unclassified" || !status ? " — pending review" : "";
  return h("span", { class: "obligation-tag obligation-" + (obligation || "unclassified"), title: status === "draft" ? "Inferred from the benchmark's note wording; awaiting expert confirmation" : "" }, text + suffix);
}

function sourceLine(provenance) {
  if (!provenance) return null;
  const pending = !provenance.citation;
  return h("div", { class: "source-line" + (pending ? " source-pending" : "") }, "Source: " + provenance.citationLabel);
}

function provenanceBlock(provenance) {
  if (!provenance) return null;
  return h("div", { class: "provenance" }, [obligationBadge(provenance.obligation, provenance.obligationStatus), sourceLine(provenance)]);
}

function fallbackBlock(fallback) {
  if (!fallback) return null;
  const bound = fallback.required ? fallback.required : [fallback.min, fallback.max].every((v) => v != null) ? `${fallback.min}–${fallback.max}` : fallback.min != null ? `≥ ${fallback.min}` : `≤ ${fallback.max}`;
  return h("div", { class: "fallback-block" }, [
    h("span", { class: "fallback-tag" }, fallback.label),
    h("span", { class: "status-pill " + statusPillClass(fallback.status) }, statusLabel(fallback.status)),
    h("div", { class: "field-note" }, `Reference ${bound}${fallback.note ? " — " + fallback.note : ""}. Advisory only; not this authority's requirement.`),
  ]);
}

// Labels for ResultsModel: ids in the compact snapshot -> display names.
function resultLabels() {
  return {
    market: marketLabel,
    room: (id) => (DATA.roomById[id] || {}).name || id,
    param: (id) => (DATA.paramById[id] || {}).name || (id === "DIM-001-area" ? "Room Net Area" : id),
    threshold: (id) => (DATA.boolean_thresholds.find((b) => b.id === id) || {}).parameter_name || id,
  };
}

function renderStep4() {
  const root = document.getElementById("step-4");
  clear(root);

  // A saved project whose data/engine changed shows its results as saved,
  // read-only, until the user re-evaluates (banner in the project bar). It
  // renders through the same ResultsModel/ResultsView as the live page.
  if (CURRENT && !CURRENT.reevaluated && CURRENT.results && CURRENT.results.status === "stale") {
    if (CURRENT.results.snapshot) root.appendChild(ProjectsView.snapshotSummary(h, s, CURRENT.results.snapshot, resultLabels()));
    return;
  }

  const all = FacilityEngine.evaluateAll(DATA, state);
  const { rows, booleanRows, recommendations: recs, structural } = all;
  const labels = resultLabels();

  const panel = h("div", { class: "panel results-panel" });
  panel.appendChild(h("h2", {}, "Step 4 — Compliance Results"));

  structural.forEach((f) => {
    panel.appendChild(h("div", { class: "structural-banner" }, [h("strong", {}, "Regulatory vacuum flagged"), f.message]));
  });

  panel.appendChild(
    h("div", { class: "advisory-note" }, "Advisory only — not a regulatory sign-off. Mandatory/Recommended labels marked “draft” and sources marked “pending” are awaiting domain-expert review. “International/industry standard (fallback)” is shown where an authority gives no number, and never counts toward that authority's verdict.")
  );

  const model = ResultsModel.build(ResultsSnapshot.compact(all, state), labels);
  panel.appendChild(ResultsView.resultsPage(h, s, model, { numeric: ResultsModel.numericGaps(rows, state.targetMarkets, labels), labels }));

  // The full tables, recommendation text and sources stay available, collapsed.
  const detail = h("div", { class: "full-detail-body" });
  panel.appendChild(h("details", { class: "full-detail" }, [h("summary", {}, "Full detail — every check, recommendation text and source"), detail]));

  detail.appendChild(h("h3", {}, "Recommended Modifications"));
  if (!recs.length) {
    detail.appendChild(h("p", { class: "empty-hint" }, "No non-compliant parameters found among selected markets — either everything entered checks out, or no values have been entered yet."));
  } else {
    recs.forEach((r) => {
      const isFallback = r.basis === "fallback";
      detail.appendChild(
        h("div", { class: "recommendation rec-" + r.severity.toLowerCase() + (isFallback ? " rec-fallback" : "") }, [
          h("div", { class: "rec-title" }, [
            h("span", { class: "severity-tag " + severityTagClass(r.severity) }, r.severity),
            obligationBadge(r.obligation, r.obligationStatus),
            isFallback ? h("span", { class: "fallback-tag" }, "International/industry standard (fallback)") : null,
          ]),
          h("div", {}, r.text),
          h("div", { class: "source-line" + (r.citations.every((c) => c === FacilityEngine.PENDING_CITATION) ? " source-pending" : "") }, "Source: " + r.citations.join("; ")),
        ])
      );
    });
  }

  detail.appendChild(h("h3", {}, "Detailed Parameter Status"));
  const tableScroll = h("div", { class: "table-scroll" });
  const table = h("table", { class: "results-table" });
  const headRow = h("tr", {}, [h("th", {}, "Room"), h("th", {}, "Parameter"), h("th", {}, "Entered"), h("th", {}, "Severity")].concat(state.targetMarkets.map((mk) => h("th", {}, marketLabel(mk)))));
  table.appendChild(h("thead", {}, headRow));
  const tbody = h("tbody");
  rows.forEach((row) => {
    const enteredDisplay = row.entered === null || row.entered === undefined || row.entered === "" ? "—" : typeof row.entered === "object" ? `${row.entered.min ?? "?"}–${row.entered.max ?? "?"}` : String(row.entered);
    const sev = row.threshold.severity || (row.param && row.param.gap_severity) || "Partial";
    const conflict = row.evalResult.conflict;
    const paramCell = h("td", {}, row.param.name);
    if (conflict) {
      const ref = conflict.reference;
      paramCell.appendChild(
        h("div", { class: "conflict-note" }, `Authorities conflict (${conflict.markets.map(marketLabel).join(", ")}): no single value satisfies all.` +
          (ref ? ` ${ref.label}: ${ref.min ?? "?"}–${ref.max ?? "?"}${ref.note ? " — " + ref.note : ""}.` : " No fallback standard in dataset."))
      );
    }
    const tr = h("tr", {}, [
      h("td", {}, row.room ? row.room.name : "Facility"),
      paramCell,
      h("td", {}, enteredDisplay),
      h("td", {}, h("span", { class: "severity-tag " + severityTagClass(sev) }, sev)),
    ]);
    state.targetMarkets.forEach((mk) => {
      const r = row.evalResult.perMarket[mk] || { status: "no_value" };
      const cell = h("td", {}, h("span", { class: "status-pill " + statusPillClass(r.status) }, statusLabel(r.status)));
      if (r.note) cell.appendChild(h("div", { class: "field-note" }, r.note));
      const prov = provenanceBlock(r.provenance);
      if (prov) cell.appendChild(prov);
      const fb = fallbackBlock(r.fallback);
      if (fb) cell.appendChild(fb);
      tr.appendChild(cell);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  tableScroll.appendChild(table);
  detail.appendChild(tableScroll);

  if (booleanRows.length) {
    detail.appendChild(h("h3", {}, "Required-Feature Checklist"));
    const btable = h("table", { class: "results-table" });
    btable.appendChild(h("thead", {}, h("tr", {}, [h("th", {}, "Room"), h("th", {}, "Feature"), h("th", {}, "Entered"), h("th", {}, "Severity"), h("th", {}, "Status"), h("th", {}, "Requirement & source")])));
    const btbody = h("tbody");
    booleanRows.forEach((br) => {
      btbody.appendChild(
        h("tr", {}, [
          h("td", {}, br.room ? br.room.name : "Facility"),
          h("td", {}, br.threshold.parameter_name),
          h("td", {}, br.entered === true ? "Yes" : br.entered === false ? "No" : "—"),
          h("td", {}, h("span", { class: "severity-tag " + severityTagClass(br.threshold.severity) }, br.threshold.severity)),
          h("td", {}, h("span", { class: "status-pill " + statusPillClass(br.status) }, statusLabel(br.status))),
          h("td", {}, provenanceBlock(br.provenance)),
        ])
      );
    });
    btable.appendChild(btbody);
    detail.appendChild(h("div", { class: "table-scroll" }, btable));
  }

  const scoredIds = new Set(
    DATA.thresholds.map((t) => t.linked_param_id)
      .concat(DATA.boolean_thresholds.map((b) => b.linked_param_id))
      .concat(["DIM-001", "HVAC-001"])
  );
  const infoParams = relevantParams().filter((p) => !scoredIds.has(p.id));
  if (infoParams.length) {
    detail.appendChild(h("h3", {}, "Captured, Not Auto-Checked (free text / no comparable regulatory value in this dataset)"));
    const selectedRoomsForInfo = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);
    infoParams.forEach((p) => {
      const renderCard = (label, val) =>
        detail.appendChild(
          h("div", { class: "info-card" }, [
            h("span", { class: "info-label" }, label + ": "),
            h("span", {}, val === null || val === undefined || val === "" ? "(not entered)" : typeof val === "object" ? JSON.stringify(val) : String(val)),
            h("div", { class: "info-note" }, p.notes || ""),
          ])
        );
      if (appliesAtNormalized(p) === "facility") {
        renderCard(p.name, state.facilityValues[p.id]);
      } else {
        selectedRoomsForInfo.forEach((room) => {
          const filter = PARAM_ROOM_FILTERS[p.id];
          if (filter && !filter(room)) return;
          renderCard(`${p.name} (${room.name})`, (state.roomValues[room.id] || {})[p.id]);
        });
      }
    });
  }

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Navigation
// ---------------------------------------------------------------------

function updateStepIndicator() {
  document.querySelectorAll("#step-indicator li").forEach((li) => {
    const n = parseInt(li.dataset.step, 10);
    li.classList.toggle("active", n === state.step);
    li.classList.toggle("done", n < state.step);
  });
}

function showStep(n) {
  state.step = n;
  [1, 2, 3, 4].forEach((i) => {
    document.getElementById("step-" + i).hidden = i !== n;
  });
  updateStepIndicator();
  if (n === 1) renderStep1();
  if (n === 2) renderStep2();
  if (n === 3) renderStep3();
  if (n === 4) renderStep4();

  document.getElementById("btn-back").disabled = n === 1;
  document.getElementById("btn-next").hidden = n === 4;
  document.getElementById("btn-restart").hidden = n !== 4;
  renderProjectBar();
  scrollToTop();
}

function validateStep(n) {
  if (n === 1) {
    if (!state.category) return "Pick a dosage form category first.";
    if (!state.specificForms.length) return "Select at least one specific dosage form.";
    if (!state.targetMarkets.length) return "Select at least one target regulatory market.";
    if (state.category === "osd_rnd_pilot" && !state.devStage) return "Select the facility development stage.";
  }
  if (n === 2) {
    if (!state.selectedRooms.length) return "Select at least one room/zone.";
  }
  return null;
}

function wireNav() {
  document.getElementById("btn-back").addEventListener("click", () => {
    if (state.step > 1) showStep(state.step - 1);
  });
  document.getElementById("btn-next").addEventListener("click", () => {
    const err = validateStep(state.step);
    if (err) { alert(err); return; }
    showStep(Math.min(4, state.step + 1));
  });
  document.getElementById("btn-restart").addEventListener("click", () => {
    // In a saved project "Start Over" opens a new project rather than
    // blanking this one (a later Save would overwrite it).
    if (CURRENT) return go("#/projects/new");
    ProjectState.resetState(state);
    showStep(1);
  });
}

// ---------------------------------------------------------------------
// Accounts, routing and views
// ---------------------------------------------------------------------

let SB = null; // supabase-js client; null when config.js is absent (wizard only, no saving)
let AUTH = null;
let SESSION = null;
let AUTH_LINK_ERROR = false; // the email link that opened the app was invalid or expired
let currentView = null;

// Smooth scrolling unless the user asked for reduced motion.
function scrollToTop() {
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  window.scrollTo({ top: 0, behavior: reduce ? "auto" : "smooth" });
}

const VIEWS = ["view-signin", "view-projects", "view-message", "view-wizard"];

function showView(id) {
  currentView = id;
  VIEWS.forEach((v) => (document.getElementById(v).hidden = v !== id));
  const wizard = id === "view-wizard";
  document.getElementById("step-indicator").hidden = !wizard;
  document.getElementById("wizard-nav").hidden = !wizard;
}

function go(hash) {
  if (window.location.hash === hash) render();
  else window.location.hash = hash; // triggers render via hashchange
}

function setNotice(el, text, isError) {
  clear(el);
  el.appendChild(document.createTextNode(text));
  el.className = "notice" + (isError ? " notice-error" : " notice-ok");
  el.hidden = false;
}

function render() {
  const route = Router.routeFor(window.location.hash, { configured: !!SB, signedIn: !!SESSION });
  const stayingOnProject = route.name === "project" && CURRENT && route.id === CURRENT.id;
  if (currentView === "view-wizard" && !stayingOnProject && hasUnsavedChanges()) {
    // Put the address back and ask first; navigate only if the user agrees.
    const target = window.location.hash;
    window.history.replaceState(null, "", lastHash || "#/projects");
    return confirmLeave(() => go(target));
  }
  lastHash = window.location.hash;
  renderToken++;
  renderAccountBar();
  if (route.name !== "new" && route.name !== "project") CURRENT = null;
  switch (route.name) {
    case "wizard-only":
      if (currentView !== "view-wizard") { showView("view-wizard"); showStep(state.step); }
      return;
    case "signin":
      return renderSignIn();
    case "projects":
      return renderProjects();
    case "new":
      return startNewProject();
    case "project":
      if (CURRENT && CURRENT.id === route.id && currentView === "view-wizard") return; // already open (e.g. just saved)
      return openProject(route.id);
    default:
      return renderMessage("Page not found", "That address doesn't match anything in the app.");
  }
}

function renderAccountBar() {
  const bar = document.getElementById("account-bar");
  clear(bar);
  if (!SB) {
    bar.appendChild(h("span", { class: "account-note" }, "Saving is off — no account service configured"));
    bar.hidden = false;
    return;
  }
  if (!SESSION) { bar.hidden = true; return; }
  bar.appendChild(h("a", { href: "#/projects" }, "My projects"));
  bar.appendChild(h("span", { class: "account-email" }, SESSION.user.email || ""));
  bar.appendChild(
    h("button", {
      type: "button",
      class: "secondary small",
      onclick: () => confirmLeave(async () => {
        await AUTH.signOut().catch(() => {});
        SESSION = null;
        CURRENT = null;
        go("#/signin");
      }),
    }, "Sign out")
  );
  bar.hidden = false;
}

const SIGNIN_MESSAGES = {
  ok: "Check your inbox — a sign-in link is on its way. It works once and expires after 1 hour.",
  invalid_email: "Enter a valid email address.",
  rate_limited: "Too many requests. Wait a minute, then try again.",
  network: "Couldn't reach the server. Check your connection and try again.",
};

function renderSignIn() {
  const root = document.getElementById("view-signin");
  clear(root);
  showView("view-signin");
  const panel = h("div", { class: "panel narrow-panel" });
  panel.appendChild(h("h2", {}, "Sign in"));
  panel.appendChild(h("p", { class: "field-hint" }, "We'll email you a one-time sign-in link — no password needed. Your saved projects are private to your account."));
  if (AUTH_LINK_ERROR) {
    panel.appendChild(h("div", { class: "notice notice-error", role: "alert" }, "That sign-in link has expired or was already used. Request a new one below."));
  }
  const status = h("div", { class: "notice", role: "status", hidden: "hidden" });
  const input = h("input", { type: "email", id: "signin-email", name: "email", autocomplete: "email", required: "required", maxlength: "254", placeholder: "you@company.com" });
  const button = h("button", { type: "submit" }, "Email me a sign-in link");
  const form = h(
    "form",
    {
      class: "signin-form",
      novalidate: "novalidate",
      onsubmit: async (e) => {
        e.preventDefault();
        button.disabled = true;
        const r = await AUTH.sendLink(input.value).catch(() => ({ ok: false, reason: "network" }));
        button.disabled = false;
        setNotice(status, SIGNIN_MESSAGES[r.ok ? "ok" : r.reason] || SIGNIN_MESSAGES.network, !r.ok);
      },
    },
    [h("div", { class: "field-block" }, [h("label", { for: "signin-email" }, "Work email"), input]), button]
  );
  panel.appendChild(form);
  panel.appendChild(status);
  root.appendChild(panel);
  input.focus && input.focus();
}

function renderMessage(title, text) {
  const root = document.getElementById("view-message");
  clear(root);
  showView("view-message");
  root.appendChild(
    h("div", { class: "panel narrow-panel" }, [
      h("h2", {}, title),
      h("p", {}, text),
      SB && SESSION ? h("a", { href: "#/projects" }, "Back to my projects") : null,
    ])
  );
}

// ---------------------------------------------------------------------
// Saved projects
// ---------------------------------------------------------------------

let STORE = null;
let CURRENT = null; // open project { id|null, name, notes, results, retention, reevaluated }; null = wizard-only
let renderToken = 0; // bumps on every route render so slow responses can't paint over a newer view
let saveMessage = null; // shown once in the project bar after a save
let pendingLeave = null; // navigation waiting on the unsaved-changes prompt
let lastHash = ""; // hash of the view on screen, restored when leaving is put on hold

// Unsaved changes: compare what Save would store now with what was last
// opened or saved.
const currentFingerprint = () => ProjectState.fingerprint({ name: CURRENT.name, notes: CURRENT.notes, state });
const hasUnsavedChanges = () => !!(CURRENT && CURRENT.savedFingerprint !== currentFingerprint());

function setCurrent(fields) {
  CURRENT = { reevaluated: false, ...fields };
  CURRENT.savedFingerprint = currentFingerprint();
}

function refreshUnsavedFlag() {
  const flag = document.querySelector("#project-bar .unsaved-flag");
  if (flag) flag.hidden = !hasUnsavedChanges();
}

// Run proceed() now, or after the user answers the unsaved-changes prompt.
function confirmLeave(proceed) {
  if (!hasUnsavedChanges()) return proceed();
  pendingLeave = proceed;
  renderProjectBar();
  scrollToTop();
}

function leaveNow() {
  const proceed = pendingLeave;
  pendingLeave = null;
  if (CURRENT) CURRENT.savedFingerprint = currentFingerprint(); // changes discarded on purpose
  if (proceed) proceed();
}

const fmtDate = (d) => ProjectsView.formatDate(d);

function errorText(e) {
  if (e && e.code === "invalid") return "Can't save yet: " + e.errors.join("; ");
  if (e && e.code === "invalid_project") return "This saved project couldn't be loaded safely.";
  if (e && e.serverCode === "PGRST301") return "Your session has expired. Sign in again.";
  return "Couldn't reach the server. Check your connection and try again.";
}

async function renderProjects() {
  const token = renderToken;
  CURRENT = null;
  const root = document.getElementById("view-projects");
  clear(root);
  showView("view-projects");
  const body = h("div", {}, h("p", { class: "field-hint" }, "Loading your projects…"));
  root.appendChild(
    h("div", { class: "panel" }, [
      h("div", { class: "projects-head" }, [
        h("h2", {}, "Your projects"),
        h("button", { type: "button", onclick: () => go("#/projects/new") }, "New project"),
      ]),
      h("p", { class: "field-hint" }, "A project is deleted 6 months after its last edit, with a 30-day warning first. Opening a project doesn't count as an edit."),
      body,
    ])
  );
  try {
    const items = await STORE.list();
    if (token !== renderToken) return;
    clear(body);
    body.appendChild(
      ProjectsView.projectList(h, items, {
        onKeep: (p) => STORE.keep(p.id).then(() => token === renderToken && renderProjects(), showListError),
        onDelete: (p) => STORE.remove(p.id).then(() => token === renderToken && renderProjects(), showListError),
      }, fmtDate)
    );
  } catch (e) {
    if (token === renderToken) showListError(e);
  }
  function showListError(e) {
    clear(body);
    body.appendChild(h("div", { class: "notice notice-error", role: "alert" }, errorText(e)));
  }
}

function startNewProject() {
  ProjectState.resetState(state);
  setCurrent({ id: null, name: "", notes: "", results: null, retention: null });
  showView("view-wizard");
  showStep(1);
}

async function openProject(id) {
  const token = renderToken;
  renderMessage("Opening project…", "");
  let p;
  try {
    p = await STORE.get(id);
  } catch (e) {
    if (token === renderToken) renderMessage("Couldn't open this project", errorText(e));
    return;
  }
  if (token !== renderToken) return;
  if (!p) return renderMessage("Project not found", "It may have been deleted, or the link is wrong.");
  ProjectState.resetState(state, p.inputs);
  setCurrent({ id: p.id, name: p.name, notes: p.notes, results: p.results, retention: p.retention });
  showView("view-wizard");
  // Complete projects open on their results; unfinished ones where they start.
  showStep(!validateStep(1) && !validateStep(2) ? 4 : 1);
}

function renderProjectBar() {
  const bar = document.getElementById("project-bar");
  clear(bar);
  if (!CURRENT) { bar.hidden = true; return; }
  bar.hidden = false;
  const status = h("span", { class: "save-status", role: "status" }, saveMessage || "");
  saveMessage = null;
  const save = h("button", { type: "button", onclick: () => saveCurrent(save, status) }, CURRENT.id ? "Save changes" : "Save project");
  bar.appendChild(
    h("div", { class: "panel project-bar" }, [
      h("div", { class: "project-bar-row" }, [
        h("a", { href: "#/projects", class: "back-link" }, "← My projects"),
        h("label", { for: "project-name", class: "visually-hidden" }, "Project name"),
        h("input", {
          type: "text", id: "project-name", maxlength: "120", value: CURRENT.name,
          placeholder: "Project name (e.g. Plant 2 — sterile block)",
          oninput: (e) => { CURRENT.name = e.target.value; refreshUnsavedFlag(); },
        }),
        save,
        h("span", { class: "unsaved-flag", hidden: hasUnsavedChanges() ? null : "hidden" }, "Unsaved changes"),
        status,
      ]),
      pendingLeave ? unsavedGuard() : null,
      h("details", { class: "project-notes" }, [
        h("summary", {}, "Notes"),
        h("textarea", { maxlength: "2000", "aria-label": "Project notes", oninput: (e) => { CURRENT.notes = e.target.value; refreshUnsavedFlag(); } }, CURRENT.notes || ""),
      ]),
      ProjectsView.deletionNotice(h, CURRENT.retention, { onKeep: keepCurrent, fmt: fmtDate }),
      CURRENT.reevaluated ? null : ProjectsView.resultsNotice(h, CURRENT.results, { onReevaluate: reevaluate }),
    ])
  );
}

function unsavedGuard() {
  const status = h("span", { class: "save-status", role: "status" });
  const save = h("button", { type: "button", onclick: async () => { if (await saveCurrent(save, status)) leaveNow(); } }, "Save and leave");
  return h("div", { class: "unsaved-guard", role: "alertdialog", "aria-label": "Unsaved changes" }, [
    h("strong", {}, "You have unsaved changes."),
    h("span", {}, " Save them before leaving this project?"),
    save,
    h("button", { type: "button", class: "secondary", onclick: leaveNow }, "Discard changes"),
    h("button", { type: "button", class: "secondary", onclick: () => { pendingLeave = null; renderProjectBar(); } }, "Stay"),
    status,
  ]);
}

async function saveCurrent(button, status) {
  button.disabled = true;
  setNotice(status, "Saving…", false);
  try {
    const payload = { name: CURRENT.name, notes: CURRENT.notes, state };
    const p = CURRENT.id ? await STORE.update(CURRENT.id, payload) : await STORE.create(payload);
    if (!p) { renderMessage("Project not found", "It may have been deleted in another tab."); return false; }
    const wasNew = !CURRENT.id;
    setCurrent({ id: p.id, name: p.name, notes: p.notes, results: p.results, retention: p.retention });
    // Give the new project its own address without re-running the router.
    if (wasNew) {
      window.history.replaceState(null, "", "#/projects/" + p.id);
      lastHash = window.location.hash;
    }
    saveMessage = "Saved";
    showStep(state.step);
    return true;
  } catch (e) {
    setNotice(status, errorText(e), true);
    return false;
  } finally {
    button.disabled = false;
  }
}

async function keepCurrent() {
  try {
    const p = await STORE.keep(CURRENT.id);
    if (!p) return renderMessage("Project not found", "It may have been deleted in another tab.");
    CURRENT.retention = p.retention;
    saveMessage = "Kept — the 6-month clock has restarted";
    renderProjectBar();
  } catch (e) {
    renderProjectBar();
    setNotice(document.querySelector("#project-bar .save-status"), errorText(e), true);
  }
}

function reevaluate() {
  CURRENT.reevaluated = true;
  saveMessage = "Showing results with the current data — save to update the project";
  showStep(4);
}

async function initAccounts() {
  const cfg = window.APP_CONFIG;
  if (!cfg || !cfg.supabaseUrl || !cfg.supabaseAnonKey || !window.supabase) return;
  const href = window.location.href;
  AUTH_LINK_ERROR = /[?&#]error(_code)?=/.test(href);
  SB = window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, {
    // PKCE: the email link comes back with a one-time ?code=, never tokens in the URL.
    auth: { flowType: "pkce", detectSessionInUrl: true, persistSession: true, autoRefreshToken: true },
  });
  AUTH = Auth.createAuth({ client: SB, location: window.location });
  const manifest = await fetch("data/manifest.json").then((r) => r.json());
  STORE = ProjectStore.createStore({
    client: SB,
    DATA,
    versions: { dataHash: manifest.content_hash, engineVersion: FacilityEngine.ENGINE_VERSION },
    ProjectState,
    ResultsSnapshot,
  });
  try {
    const { data, error } = await SB.auth.getSession(); // completes an email-link sign-in if ?code= is present
    if (error) AUTH_LINK_ERROR = true;
    SESSION = (data && data.session) || null;
  } finally {
    const clean = Router.scrubAuthParams(href); // R15: no codes or tokens left in the address bar
    if (clean !== href) window.history.replaceState(null, "", clean);
  }
  SB.auth.onAuthStateChange((_event, session) => {
    const changed = !!session !== !!SESSION;
    SESSION = session;
    if (changed) setTimeout(render, 0); // never call back into supabase-js inside this callback
  });
}

// ---------------------------------------------------------------------
// Init
// ---------------------------------------------------------------------

async function init() {
  DATA = await loadData();
  wireNav();
  await initAccounts();
  window.addEventListener("hashchange", render);
  // Closing or reloading the tab with unsaved changes: the browser's own prompt.
  window.addEventListener("beforeunload", (e) => {
    if (hasUnsavedChanges()) { e.preventDefault(); e.returnValue = ""; }
  });
  const wizard = document.getElementById("view-wizard");
  if (wizard.addEventListener) ["input", "change", "click"].forEach((t) => wizard.addEventListener(t, () => setTimeout(refreshUnsavedFlag, 0)));
  render();
}

init();
